<script setup>
import {computed,ref,watch} from 'vue';
import {Head,Link,usePage,useForm} from '@inertiajs/vue3';
import ProviderStart from '@/Pages/Marketplace/ProviderStart.vue';
import GettingStartedModal from '@/Components/Onboarding/GettingStartedModal.vue';
const props=defineProps({service:String,status:String,application:Object,requirements:{type:Object,default:()=>({})}});
const page=usePage(),open=ref(true),step=ref(0),editing=ref(false),selectionError=ref('');
const titles={spaces:'Landlord',haul:'UV Owner',raketeer:'Raketeer'};
const steps=['About you','Your offering','Documents','Review'];
const user=page.props.auth.user,preferences=page.props.auth.onboarding?.data||{};
const initial=()=>({version:props.application?.version||null,action:'submit',displayName:props.application?.displayName||user.name,phone:props.application?.phone||'',area:props.application?.area||preferences.city||'',description:props.application?.description||'',details:{applicantType:preferences.personas?.includes('business_owner')?'business':'individual',businessName:'',relationship:'',serviceCategory:'',skills:'',experienceYears:'',...props.application?.details},documents:[],documentMeta:[],keepDocuments:(props.application?.documents||[]).map(doc=>doc.index),confirmed:false});
const form=useForm(initial());
const pending=computed(()=>props.status==='pending'&&props.application?.status==='pending');
const locked=computed(()=>pending.value||(props.status==='approved'&&!editing.value));
const statuses=computed(()=>({...page.props.auth.providerRoles,[props.service]:props.status}));
const savedDocuments=computed(()=>(props.application?.documents||[]).filter(doc=>form.keepDocuments.includes(doc.index)));
const label=type=>props.requirements[type]?.label||'Supporting document';
function choose(event){const files=Array.from(event.target.files||[]);event.target.value='';selectionError.value='';if(files.length+form.documents.length+savedDocuments.value.length>10||files.some(f=>f.size>5*1024*1024||!['image/jpeg','image/png','image/webp','application/pdf'].includes(f.type))){selectionError.value='Use JPG, PNG, WebP, or PDF files up to 5 MB each, with at most 10 documents in total.';return;}for(const file of files){form.documents.push(file);form.documentMeta.push({type:'',reference:'',expiresAt:''});}}
function removeNew(index){form.documents.splice(index,1);form.documentMeta.splice(index,1);}
function submit(action='submit'){if(form.processing)return;form.action=action;form.post(`/provider-applications/${props.service}`,{forceFormData:true,preserveScroll:true,onSuccess:()=>{Object.assign(form,initial());editing.value=false;step.value=0;},onError:errors=>{const keys=Object.keys(errors);step.value=keys.some(k=>/^(displayName|phone|details.applicantType|details.businessName)/.test(k))?0:keys.some(k=>/^(area|description|details)/.test(k))?1:keys.some(k=>/^(documents|documentMeta|keepDocuments)/.test(k))?2:3;}});}
function next(){selectionError.value='';if(step.value===2){const types=[...savedDocuments.value.map(d=>d.type),...form.documentMeta.map(d=>d.type)];const missing=Object.entries(props.requirements).filter(([type,rule])=>rule.required&&!types.includes(type));if(missing.length){selectionError.value='Please add: '+missing.map(([,r])=>r.label).join(', ');return;}}if(step.value<3)step.value++;else submit();}
watch(()=>props.service,()=>{Object.assign(form,initial());form.clearErrors();editing.value=false;step.value=0;open.value=true;});
watch(()=>props.application,app=>{form.version=app?.version||null;form.keepDocuments=(app?.documents||[]).map(doc=>doc.index);});
</script>
<template>
<ProviderStart :statuses="statuses"/>
<Head :title="titles[service]+' · Getting started'"/>
<button v-if="!open" type="button" class="provider-resume" @click="open=true">Resume {{ titles[service] }} application</button>
<GettingStartedModal :open="open" :title="locked?(pending?'Your application is under review':'You’re an approved '+titles[service]):'Get started as a '+titles[service]" :steps="locked?[]:steps" :step="step" :busy="form.processing" @close="open=false">
<div v-if="locked" class="getting-fields"><p>Approval applies to this role only. Your User account and other provider roles stay separate.</p><p v-if="application?.reviewNote" class="getting-note">{{ application.reviewNote }}</p><dl><dt>Name</dt><dd>{{ application?.displayName }}</dd><dt>Area</dt><dd>{{ application?.area }}</dd><dt>About your offering</dt><dd>{{ application?.description }}</dd></dl><div v-for="doc in application?.documents||[]" :key="doc.index"><a :href="doc.url">{{ label(doc.type) }} · {{ doc.name }}</a></div><div class="getting-actions"><button @click="open=false">Close</button><template v-if="status==='approved'"><button @click="editing=true;step=0">Update verification</button><Link :href="`/my-listings/${service}/new`" class="getting-link">Create listing</Link></template></div></div>
<form v-else @submit.prevent="next">
<p v-if="application?.reviewNote" class="getting-note"><strong>Admin feedback:</strong> {{ application.reviewNote }}</p>
<p v-if="application?.status==='draft'" class="getting-note">Your saved draft is ready to continue.</p>
<p v-if="status==='approved'" class="getting-note">Submitting updated verification puts this role back under review. Listing tools will be unavailable until it is approved again.</p>
<div v-if="Object.keys(form.errors).length" role="alert" class="getting-errors"><div v-for="(error,key) in form.errors" :key="key">{{ error }}</div></div>
<template v-if="step===0"><p>Tell us who will offer {{ service==='spaces'?'the property':service==='haul'?'the vehicle':'the service' }}. We’ll send these details to the admin reviewing your application.</p><label>Applying as<select v-model="form.details.applicantType"><option value="individual">Individual</option><option value="business">Business</option></select></label><label>Display name<input v-model="form.displayName" required maxlength="255" autocomplete="name"/></label><label v-if="form.details.applicantType==='business'">Registered business name<input v-model="form.details.businessName" required maxlength="255" autocomplete="organization"/></label><label>Contact phone<input v-model="form.phone" required minlength="7" maxlength="40" type="tel" autocomplete="tel"/></label></template>
<template v-if="step===1"><p>{{ service==='spaces'?'Tell us about the space and your authority to offer it.':service==='haul'?'Tell us about your rental vehicles and your relationship to their owner.':'Tell us about your skills and the work you can offer nearby.' }}</p><label>City / service area<input v-model="form.area" maxlength="255" required/></label><label v-if="service!=='raketeer'">{{ service==='spaces'?'Relationship to property':'Relationship to registered vehicle owner' }}<input v-model="form.details.relationship" maxlength="255" placeholder="Owner or authorized representative"/></label><template v-else><label>Service category<input v-model="form.details.serviceCategory" maxlength="255" placeholder="e.g. Tutoring, repairs, design"/></label><label>Years of experience<input v-model="form.details.experienceYears" type="number" min="0" max="80"/></label><label>Skills and qualifications<textarea v-model="form.details.skills" rows="3" maxlength="1000"/></label></template><label>About your offering<textarea v-model="form.description" required minlength="20" maxlength="3000" rows="4" placeholder="Describe what you offer and who it is for (at least 20 characters)."/></label></template>
<template v-if="step===2"><p>Documents are private and accessible only to you and authorized administrators. Keep them out of your public listing gallery.</p><ul><li v-for="(rule,type) in requirements" :key="type">{{ rule.label }} — {{ rule.required?'Required':'If applicable' }}</li></ul><div v-for="doc in savedDocuments" :key="doc.index" class="getting-file"><a :href="doc.url">{{ label(doc.type) }} · {{ doc.name }}</a><button type="button" :disabled="form.processing" @click="form.keepDocuments=form.keepDocuments.filter(i=>i!==doc.index)">Remove {{ doc.name }}</button></div><label>Add documents<input type="file" multiple accept="image/jpeg,image/png,image/webp,application/pdf" :disabled="form.processing" @change="choose"/></label><p>JPG, PNG, WebP, or PDF. Up to 5 MB per file; 10 files total.</p><div v-for="(file,index) in form.documents" :key="index" class="getting-file"><strong>{{ file.name }}</strong><label>Document type<select v-model="form.documentMeta[index].type" aria-label="Document type" required><option value="" disabled>Select type</option><option v-for="(rule,type) in requirements" :value="type" :key="type">{{ rule.label }}</option></select></label><label>Property, vehicle, or qualification reference<input v-model="form.documentMeta[index].reference" maxlength="255" placeholder="e.g. Vehicle plate or property address (private)"/></label><label>Expiry date (if shown)<input v-model="form.documentMeta[index].expiresAt" type="date"/></label><button type="button" :disabled="form.processing" @click="removeNew(index)">Remove {{ file.name }}</button></div></template>
<template v-if="step===3"><p>Check your application before sending it. An administrator will review your details and documents.</p><dl><dt>Applying as</dt><dd>{{ form.details.applicantType }} · {{ form.details.businessName||form.displayName }}</dd><dt>Contact phone</dt><dd>{{ form.phone }}</dd><dt>Area</dt><dd>{{ form.area }}</dd><dt>About your offering</dt><dd>{{ form.description }}</dd><dt>{{ service==='raketeer'?'Skills / category':'Relationship' }}</dt><dd>{{ service==='raketeer'?[form.details.serviceCategory,form.details.skills,form.details.experienceYears!==''?form.details.experienceYears+' years experience':''].filter(Boolean).join(' · '):form.details.relationship||'Not provided' }}</dd><dt>Documents</dt><dd v-for="doc in savedDocuments" :key="doc.index">{{ label(doc.type) }} · {{ doc.name }}</dd><dd v-for="(file,index) in form.documents" :key="index">{{ label(form.documentMeta[index].type) }} · {{ file.name }}</dd></dl><label class="getting-check"><input v-model="form.confirmed" type="checkbox" required/>I confirm these details and documents are accurate and authorize Aadi administrators to review this application.</label></template>
<p v-if="selectionError" role="alert" class="getting-errors">{{ selectionError }}</p><p v-if="form.progress" role="status">Uploading: {{ form.progress.percentage }}%</p><p>Closing keeps your answers until you leave this page. Save a draft to return later.</p>
<div class="getting-actions"><button v-if="status!=='approved'" type="button" :disabled="form.processing" @click="submit('draft')">Save draft</button><button v-if="step>0" type="button" :disabled="form.processing" @click="step--">Back</button><button class="getting-primary" :disabled="form.processing">{{ form.processing?'Saving…':step===3?'Submit for review':'Continue' }}</button></div>
</form></GettingStartedModal>
</template>
<style scoped>.provider-resume{position:fixed;bottom:24px;right:20px;z-index:40;background:#137671;color:white;padding:12px 18px;border-radius:24px;min-height:44px;font-weight:700;font-size:13px}</style>
